// Generated by /ship test audit (Claude Fable 5.1) — 2026-10-12
// Value: protects=StudentSessionLedgerCard keeps error/empty/ready distinct: null = error slot without totals, empty = empty slot + 3 totals, alerts by severity, footer n/m;
// fails_when=a failed load paints 0-buổi totals or the empty copy, an empty ledger hides its totals, a danger alert is a status, or the footer counts the slice;
// why_new=the profile tests only assert the ledger table exists on the payments tab, none drive summary=null, entries=[], alerts, or the limit footer;
// seam=none; no_claim=does not prove the ledger read model computes balances correctly (ledger-data owns that)
import { cleanup, render, screen, within } from "@testing-library/react";
import { afterEach, describe, expect, it } from "vitest";

import { StudentSessionLedgerCard } from "@/features/students/detail/components/student-session-ledger-card";
import type { StudentLedgerReadModel } from "@/features/students/ledger-data";

afterEach(cleanup);

const entry = {
  balanceAfter: 3,
  createdAt: "2026-10-12T14:52:00Z",
  deltaSessions: -1,
  effectiveOn: "2026-10-12",
  entryType: "session_charge",
  id: "l-1",
  note: "Khóa buổi B14",
  referenceCode: "B14",
  unitPriceVnd: 200_000,
};

function buildSummary(overrides: Partial<StudentLedgerReadModel> = {}): StudentLedgerReadModel {
  return {
    alerts: [],
    balanceSessions: 3,
    entries: [entry, { ...entry, balanceAfter: 4, deltaSessions: 12, effectiveOn: "2026-09-01", entryType: "topup", id: "l-2", note: "Nạp 12 buổi", referenceCode: "YC-2609-0142" }],
    latestEntryAt: "2026-10-12T14:52:00Z",
    ledgerEntryCount: 2,
    totalCreditSessions: 12,
    totalDebitSessions: 9,
    ...overrides,
  };
}

const card = () => screen.getByRole("region", { name: "Sổ cái số buổi học" });

describe("StudentSessionLedgerCard states (design 05a)", () => {
  it("shows the error slot and no totals when the ledger failed to load", () => {
    render(<StudentSessionLedgerCard summary={null} />);

    expect(within(card()).getByText("Không tải được dữ liệu sổ cái số buổi.")).toBeInTheDocument();
    expect(screen.queryByText("Học viên chưa có lịch sử phát sinh số buổi.")).not.toBeInTheDocument();
    expect(screen.queryByText("Số dư hiện tại")).not.toBeInTheDocument();
    expect(within(card()).queryAllByRole("term")).toHaveLength(0);
    expect(screen.queryByText(/^(Còn|Âm) \d+ buổi$|^Hết buổi$/)).not.toBeInTheDocument();
    expect(screen.queryByText(/Hiển thị/)).not.toBeInTheDocument();
    expect(within(screen.getByRole("table", { name: "Sổ cái số buổi học của học sinh" })).getAllByRole("row")).toHaveLength(1);
  });

  it("keeps the three totals and the balance badge next to the empty slot", () => {
    render(<StudentSessionLedgerCard summary={buildSummary({ balanceSessions: 0, entries: [], ledgerEntryCount: 0, latestEntryAt: null, totalCreditSessions: 0, totalDebitSessions: 0 })} />);

    expect(within(card()).getByText("Học viên chưa có lịch sử phát sinh số buổi.")).toBeInTheDocument();
    expect(within(card()).getByText("Hết buổi")).toBeInTheDocument();
    const totals = within(card()).getAllByRole("term").map((term) => `${term.textContent} ${term.nextElementSibling?.textContent}`);
    expect(totals).toEqual(["Số dư hiện tại 0 buổi", "Tổng đã cộng +0 buổi", "Tổng đã trừ −0 buổi"]);
    expect(screen.queryByText(/Hiển thị/)).not.toBeInTheDocument();
  });

  it("announces alerts by severity and reports the visible slice against the ledger total", () => {
    render(
      <StudentSessionLedgerCard
        limit={1}
        summary={buildSummary({
          alerts: [
            { alertType: "negative_balance", balanceSessions: 3, description: "Liên hệ phụ huynh để gia hạn.", severity: "danger", title: "Số dư âm" },
            { alertType: "low_balance", balanceSessions: 3, description: "Còn dưới 3 buổi.", severity: "warning", title: "Sắp hết buổi" },
          ],
        })}
      />,
    );

    expect(screen.getByRole("alert")).toHaveTextContent("Số dư âm Liên hệ phụ huynh để gia hạn.");
    expect(screen.getByRole("status")).toHaveTextContent("Sắp hết buổi Còn dưới 3 buổi.");
    expect(within(card()).getByText("Còn 3 buổi")).toBeInTheDocument();

    const table = screen.getByRole("table", { name: "Sổ cái số buổi học của học sinh" });
    const rows = within(table).getAllByRole("row");
    expect(rows).toHaveLength(2);
    expect(rows[1]).toHaveTextContent("12/10/2026");
    expect(rows[1]).toHaveTextContent("Trừ buổi học");
    expect(rows[1]).toHaveTextContent("B14");
    expect(within(card()).getByText("Hiển thị 1/2 phát sinh · mới nhất 12/10/2026")).toBeInTheDocument();
  });
});
